import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares

def rot(axis,angle): return Rotation.from_rotvec(np.array(axis)*angle).as_matrix()
def trans(p=(0,0,0),R=None):
 T=np.eye(4); T[:3,3]=p
 if R is not None: T[:3,:3]=R
 return T
origins=[([0,0,.333],0),([0,0,0],-np.pi/2),([0,-.316,0],np.pi/2),([.0825,0,0],np.pi/2),([-.0825,.384,0],-np.pi/2),([0,0,0],np.pi/2),([.088,0,0],np.pi/2)]

def fk(q,tool=.0):
 T=trans([0,-.4,.78],rot([0,0,1],np.pi/2))
 for a,(p,rx) in zip(q,origins): T=T@trans(p,rot([1,0,0],rx))@trans(R=rot([0,0,1],a))
 return T@trans([0,0,.107],rot([0,0,1],-np.pi/4))@trans([0,0,tool])

if __name__=='__main__':
 import json
 p=json.load(open('/app/output/initial/meta.json'))['proprio']['now']; q=p[:7]
 actual=Rotation.from_quat([*p[20:23],p[19]]).as_matrix()
 for tool in [0,.1034]:
  T=fk(q,tool); print(tool,T,'delta',np.array(p[16:19])-T[:3,3],'rot_diff',Rotation.from_matrix(T[:3,:3].T@actual).as_rotvec())
