"""Camera-guided Panda controller, using only the public rcb_client interface.

`python gen.py replay` replays the recorded joint paths from actions.jsonl.
The approach/placement coordinates were measured from RGB-D camera images.
No simulator models, object state, or benchmark solutions are used.
"""
from pathlib import Path
import argparse,json
import numpy as np
from PIL import Image
from scipy.spatial.transform import Rotation,Slerp
from rcb_client import Robot
from kinematics import fk,ik,TOOL
OUT=Path('/app/output')

def save(res,name):
    res.save(OUT/name)
    for cam,arr in res.last.items(): Image.fromarray(arr).save(OUT/name/f'{cam}.png')
    p=res.meta['proprio']['now']
    print(json.dumps({'name':name,'steps':res.meta['control_steps'],'done':res.done,'reason':res.meta['reason'],'joints':p[:7],'fingers':p[14:16],'tcp':p[16:23]}))
    return res

def observe(r,name='observation'):
    return save(r.get_obs(include_depth=True,video='none'),name)

def run(r,A,name):
    A=np.asarray(A)
    with (OUT/'actions.jsonl').open('a') as f: f.write(json.dumps({'name':name,'actions':A.tolist(),'dt':.1})+'\n')
    res=r.submit('joint_position',A,dt=.1,cameras=None,video='none',include_depth=True,note=name)
    return save(res,name)

def move(r,p,yaw=180,duration=4.,fingers=.04,name='move'):
    obs=r.get_obs(cameras=[],video='none'); state=np.array(obs.meta['proprio']['now']); q=state[:7]
    T0=fk(q,TOOL); p0=T0[:3,3]
    Rtarget=Rotation.from_euler('z',yaw,degrees=True).as_matrix()@np.diag([1,-1,-1])
    slerp=Slerp([0,1],Rotation.from_matrix(np.array([T0[:3,:3],Rtarget])))
    A=[]; n=int(round(duration/.1))
    for i in range(n):
        t=(i+1)/n; t=t*t*(3-2*t)
        q=ik(p0+(np.array(p)-p0)*t,slerp(t).as_matrix(),q)
        A.append(np.r_[q,fingers,fingers])
    A.extend([A[-1]]*10)
    if len(A)>100: raise ValueError('chunk longer than 10 seconds')
    return run(r,A,name)

def grip(r,width,duration=2.,name='grip'):
    obs=r.get_obs(cameras=[],video='none'); p=np.array(obs.meta['proprio']['now'])
    q=p[23:30]
    return run(r,np.tile(np.r_[q,width,width],(round(duration/.1),1)),name)

def replay(r):
    records=[json.loads(s) for s in (OUT/'actions.jsonl').read_text().splitlines()]
    for rec in records:
        res=r.submit('joint_position',rec['actions'],dt=rec['dt'],cameras=['forward'],video='none',note=rec['name'])
        print(rec['name'],res.meta.get('reason'))
        if res.done: break

if __name__=='__main__':
    parser=argparse.ArgumentParser(); parser.add_argument('command',choices=['observe','move','grip','replay']); parser.add_argument('--name',default='observation'); parser.add_argument('--xyz',type=float,nargs=3); parser.add_argument('--yaw',type=float,default=180); parser.add_argument('--duration',type=float,default=4.); parser.add_argument('--width',type=float,default=.04); args=parser.parse_args(); r=Robot()
    if args.command=='observe': observe(r,args.name)
    elif args.command=='move': move(r,args.xyz,args.yaw,args.duration,args.width,args.name)
    elif args.command=='grip': grip(r,args.width,args.duration,args.name)
    else: replay(r)
